void AboutPnlAboutKey(lv_event_t *e)
{
    // Your code here
    uint32_t key = lv_indev_get_key(lv_indev_get_act());
    uint32_t child_cnt = lv_obj_get_child_cnt(ui_PnlAbout);
    uint32_t child_id = get_about_childId(child_cnt);
    LV_LOG_USER("about: child_cnt:%d,child_id:%d\n", child_cnt, child_id);
    switch (key) {
    case LV_KEY_BACKSPACE:
        lv_indev_wait_release(lv_indev_get_act());
        alv_am_win_exit(NULL, "about", NULL);
        break;
    case LV_KEY_HOME:
        if (child_id == 0) {
            lv_event_send(lv_obj_get_child(ui_PnlAbout, child_id), LV_EVENT_CLICKED, NULL);
        } else {
            child_id == 1 ? AboutBtnDeviceInfoClicked(e) : AboutBtnSDCapClicked(e);
        }
        break;
    case LV_KEY_UP:
        if (child_id != 0) {
            lv_group_focus_obj((lv_obj_get_child(ui_PnlAbout, child_id - 1)));
        } else {
            lv_group_focus_obj(lv_obj_get_child(ui_PnlAbout, child_cnt - 1));
        }
        break;
    case LV_KEY_DOWN:
        if (child_id != child_cnt - 1) {
            lv_group_focus_obj((lv_obj_get_child(ui_PnlAbout, child_id + 1)));
        } else {
            lv_group_focus_obj((lv_obj_get_child(ui_PnlAbout, 0)));
        }
        break;
    case LV_KEY_RIGHT:
        lv_event_send(lv_obj_get_child(ui_PnlAbout, child_id), LV_EVENT_CLICKED, NULL);
        break;
    default:
        LV_LOG_USER("about: Undefined keystroke event");
        break;
    }
}

